css:
/* Hosam TV — light "glass" look (blue-grey sky, frosted panels, white selection pills).
   Target: LG webOS with Chrome 53 → no CSS grid, no flex gap, no aspect-ratio, no inset, no backdrop-filter, no CSS vars in @supports tricks. */
@font-face { font-family: "Plex"; font-weight: 400; src: url(fonts/arabic-400.woff2) format("woff2"); unicode-range: U+0600-06FF, U+0750-077F, U+08A0-08FF, U+FB50-FDFF, U+FE70-FEFF; }
@font-face { font-family: "Plex"; font-weight: 500; src: url(fonts/arabic-500.woff2) format("woff2"); unicode-range: U+0600-06FF, U+0750-077F, U+08A0-08FF, U+FB50-FDFF, U+FE70-FEFF; }
@font-face { font-family: "Plex"; font-weight: 700; src: url(fonts/arabic-700.woff2) format("woff2"); unicode-range: U+0600-06FF, U+0750-077F, U+08A0-08FF, U+FB50-FDFF, U+FE70-FEFF; }
@font-face { font-family: "Plex"; font-weight: 400; src: url(fonts/latin-400.woff2) format("woff2"); unicode-range: U+0000-024F, U+2000-206F, U+2190-21FF, U+25A0-25FF, U+2600-26FF; }
@font-face { font-family: "Plex"; font-weight: 500; src: url(fonts/latin-500.woff2) format("woff2"); unicode-range: U+0000-024F, U+2000-206F, U+2190-21FF, U+25A0-25FF, U+2600-26FF; }
@font-face { font-family: "Plex"; font-weight: 700; src: url(fonts/latin-700.woff2) format("woff2"); unicode-range: U+0000-024F, U+2000-206F, U+2190-21FF, U+25A0-25FF, U+2600-26FF; }

:root {
  --sky: linear-gradient(155deg, #c6d2e3 0%, #a3b5cd 28%, #8195b3 60%, #5f7191 100%);
  --deep: #5f7191;                         /* bottom of the sky, used where images fade out */
  --fg: #ffffff; --ink: #1c2434;           /* text on sky / text on white */
  --mut: rgba(255,255,255,.82); --dim: rgba(255,255,255,.62);
  --glass: rgba(255,255,255,.2); --glass2: rgba(255,255,255,.3); --edge: rgba(255,255,255,.42);
  --shadow: 0 .5rem 1.4rem rgba(32,44,70,.28);
  --side: 3.75rem;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
html { font-size: 16px; }
body {
  width: 100vw; height: 100vh; overflow: hidden; background: #8195b3; background-image: var(--sky); color: var(--fg);
  font-family: "Plex", "LG Smart UI", Tahoma, Arial, sans-serif; font-size: 1rem; line-height: 1.5;
  -webkit-user-select: none; user-select: none; -webkit-font-smoothing: antialiased;
  text-shadow: 0 .06rem .2rem rgba(30,42,66,.28);
}
.layer { position: fixed; top: 0; left: 0; width: 100%; height: 100%; display: none; background: #8195b3; background-image: var(--sky); overflow: hidden; }
.layer.on { display: block; }
.msg { color: var(--mut); min-height: 1.5rem; margin-top: .6rem; text-align: center; }
.msg.err { color: #ffe1dc; }
.mono { direction: ltr; text-align: left; font-family: monospace; white-space: pre-wrap; font-size: .85rem; }
.brand { font-size: 1.5rem; font-weight: 400; direction: ltr; letter-spacing: .01em; }
.brand b { font-weight: 700; }
.clock { color: var(--mut); font-size: 1.1rem; direction: ltr; font-weight: 500; }

/* glass + pills */
.glass { background: var(--glass); border: .07rem solid var(--edge); box-shadow: var(--shadow); }
.pill {
  display: inline-block; padding: .62rem 1.6rem; border-radius: 2rem; background: var(--glass2); color: var(--fg);
  border: .07rem solid var(--edge); font-weight: 500; font-size: 1rem; white-space: nowrap; transition: transform .15s ease-out;
}
.pill.small { padding: .36rem 1.05rem; font-size: .88rem; }
.pill.wide { display: block; text-align: center; }
.pill.focus, .pill.on2.focus { background: #fff; color: var(--ink); transform: scale(1.06); text-shadow: none; box-shadow: var(--shadow); }
.round { display: inline-block; width: 2.9rem; height: 2.9rem; border-radius: 50%; background: var(--glass2); border: .07rem solid var(--edge); text-align: center; line-height: 2.75rem; font-size: 1.35rem; font-weight: 500; transition: transform .18s; }
.round.focus { background: #fff; color: var(--ink); transform: scale(1.1); text-shadow: none; }

input {
  width: 100%; padding: .7rem 1rem; font-size: 1.05rem; font-family: inherit; color: var(--fg);
  background: var(--glass2); border: .1rem solid var(--edge); border-radius: .8rem; outline: none; text-shadow: none;
}
input::-webkit-input-placeholder { color: rgba(255,255,255,.75); }
input.focus, input:focus { border-color: #fff; background: #fff; color: var(--ink); }

/* login */
#login.on { display: flex; align-items: center; justify-content: center; }
.loginbox { width: 28rem; padding: 2rem 2.2rem; border-radius: 1.4rem; background: var(--glass); border: .07rem solid var(--edge); box-shadow: var(--shadow); }
.loginbox .brand { text-align: center; font-size: 2.2rem; }
.loginbox .hint { text-align: center; color: var(--mut); margin: .2rem 0 1rem; }
.loginbox label { display: block; margin: .8rem 0 .3rem; color: var(--mut); font-size: .88rem; }
.loginbox .pill { margin-top: 1.5rem; }

/* chooser */
.ch-top { display: flex; justify-content: space-between; align-items: center; padding: 1.8rem var(--side) 0; }
.ch-q { text-align: center; font-size: 1.9rem; font-weight: 700; margin-top: 3.2rem; }
.ch-row { display: flex; justify-content: center; margin-top: 2.6rem; }
.tile { width: 20rem; margin: 0 1.4rem; text-align: center; }
.tile-art {
  position: relative; height: 12rem; border-radius: 1.3rem; display: flex; align-items: center; justify-content: center;
  transition: transform .22s ease; overflow: hidden; border: .07rem solid var(--edge); box-shadow: var(--shadow);
}
.tile-art svg { width: 5rem; height: 5rem; }
.tile-art.vod { background: linear-gradient(140deg, rgba(255,255,255,.42) 0%, rgba(120,140,180,.45) 100%); }
.tile-art.live { background: linear-gradient(140deg, rgba(255,190,190,.5) 0%, rgba(160,80,100,.5) 100%); }
.tile.focus .tile-art { transform: scale(1.08); border-color: #fff; box-shadow: 0 .9rem 2rem rgba(32,44,70,.38); }
.tile-t { margin-top: 1.1rem; font-size: 1.25rem; font-weight: 500; color: var(--mut); }
.tile.focus .tile-t { color: var(--fg); }
.soon { position: absolute; top: .8rem; left: .8rem; padding: .1rem .7rem; border-radius: 1rem; font-size: .8rem; }
.tile-art.live .soon { background: #e5243b; font-weight: 700; direction: ltr; text-shadow: none; }
.ch-foot { position: absolute; bottom: 2rem; width: 100%; text-align: center; }

/* ===== top bar: brand · tabs · icons ===== */
#tabs { position: absolute; top: 0; left: 0; width: 100%; z-index: 20; display: flex; align-items: center; justify-content: space-between; padding: 1.3rem var(--side) 0; transition: transform .3s ease, opacity .3s ease; }
#tabs.hide { transform: translateY(-140%); opacity: 0; }
.tb-brand { width: 12rem; font-size: 1.45rem; direction: ltr; text-align: right; }
.tb-brand b { font-weight: 700; }
#tabbar { display: flex; align-items: center; background: var(--glass); border: .07rem solid var(--edge); border-radius: 2rem; padding: .28rem; box-shadow: var(--shadow); }
#tabicons { width: 12rem; display: flex; justify-content: flex-end; }
.tab { padding: .42rem 1.3rem; border-radius: 1.6rem; color: var(--mut); font-weight: 500; font-size: 1rem; margin: 0 .1rem; transition: transform .15s; }
.tab.sel { color: var(--ink); background: rgba(255,255,255,.88); text-shadow: none; }
.tab.focus { background: #fff; color: var(--ink); transform: scale(1.07); text-shadow: none; box-shadow: var(--shadow); }
.tab.icon { width: 2.9rem; height: 2.9rem; padding: 0; margin: 0 .7rem 0 0; border-radius: 50%; background: var(--glass2); border: .07rem solid var(--edge); display: flex; align-items: center; justify-content: center; color: var(--fg); }
.tab.icon.sel { background: rgba(255,255,255,.88); color: var(--ink); }
.tab.icon.focus { background: #fff; color: var(--ink); }
.tab svg { width: 1.25rem; height: 1.25rem; }

#pages { position: absolute; top: 0; left: 0; width: 100%; height: 100%; }
.page { position: absolute; top: 0; left: 0; width: 100%; height: 100%; display: none; }
.page.on { display: block; }
.pin { position: absolute; top: 0; left: 0; width: 100%; transition: transform .25s ease-out; padding-bottom: 6rem; will-change: transform; }
.page-head { padding: 5.6rem var(--side) .4rem; font-size: 2rem; font-weight: 700; }

/* ===== hero (home) ===== */
.hero { position: relative; height: 31.5rem; overflow: hidden; }
.hero-bg { position: absolute; top: 0; left: 0; width: 100%; height: 100%; -webkit-mask-image: linear-gradient(to bottom, #000 0%, #000 55%, rgba(0,0,0,0) 100%); }
.hero-bg img { position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; }
.hero-bg img.blur, #d-bg img.blur { filter: blur(26px) brightness(.85); transform: scale(1.2); }
.hero-post { position: absolute; left: 7rem; top: 6.5rem; width: 11.5rem; border-radius: .9rem; box-shadow: 0 .8rem 1.8rem rgba(20,30,50,.45); border: .07rem solid var(--edge); }
.hero-shade { position: absolute; top: 0; left: 0; width: 100%; height: 100%;
  background: linear-gradient(to left, rgba(40,52,78,.62) 0%, rgba(40,52,78,.25) 40%, rgba(40,52,78,0) 65%),
              linear-gradient(to bottom, rgba(40,52,78,.35) 0%, rgba(40,52,78,0) 22%);
  -webkit-mask-image: linear-gradient(to bottom, #000 0%, #000 55%, rgba(0,0,0,0) 100%); }
.hero-txt { position: absolute; right: var(--side); bottom: 3.2rem; width: 32rem; }
.hero-kicker { color: var(--mut); font-size: .85rem; font-weight: 500; letter-spacing: .04em; margin-bottom: .3rem; }
.hero-title { font-size: 2.9rem; font-weight: 700; line-height: 1.15; margin-bottom: .5rem; max-height: 6.8rem; overflow: hidden; text-shadow: 0 .15rem .8rem rgba(20,30,50,.45); }
.hero-meta { color: var(--mut); font-size: .95rem; margin-bottom: .45rem; }
.hero-plot { color: rgba(255,255,255,.92); font-size: .95rem; line-height: 1.55; max-height: 2.95rem; overflow: hidden; margin-bottom: 1.1rem; }
.hero-btns .pill, .hero-btns .round, #d-btns .pill, #d-btns .round { margin-left: .8rem; vertical-align: middle; }
.hero-btns .pill:first-child, #d-btns .pill:first-child { background: rgba(255,255,255,.92); color: var(--ink); text-shadow: none; }
.dots { position: absolute; right: var(--side); bottom: 1.6rem; direction: ltr; }
.dots i { display: inline-block; width: .45rem; height: .45rem; border-radius: 50%; background: rgba(255,255,255,.5); margin-right: .4rem; transition: width .2s; }
.dots i.on { background: #fff; width: 1.2rem; border-radius: .3rem; }

/* ===== shelves (home, search) ===== */
.shelf { padding: .5rem 0 .1rem; }
.shelf h3 { padding: 0 var(--side); font-size: 1.25rem; font-weight: 700; margin-bottom: .1rem; color: var(--fg); }
.shelf h3 small { color: var(--dim); font-weight: 400; font-size: .85rem; margin-right: .6rem; }
.sv { padding: .9rem var(--side) 1.4rem; }
.track { display: flex; transition: transform .22s ease-out; }
.shelf.empty .sv { height: 4rem; }
.shelf .none { color: var(--dim); padding: .6rem 0; }

/* ===== cards ===== */
.card { flex: none; margin-left: 1.15rem; position: relative; }
.card .art {
  position: relative; overflow: hidden; border-radius: .9rem; background: rgba(255,255,255,.22);
  border: .07rem solid rgba(255,255,255,.35); box-shadow: 0 .35rem .9rem rgba(32,44,70,.25);
  transition: transform .16s ease-out;
}
.card.poster { width: 9.2rem; }
.card.poster .art { height: 13.8rem; }
.card.wide { width: 16rem; }
.card.wide .art { height: 9rem; }
.card.ep { width: 14rem; }
.card.ep .art { height: 7.875rem; }
.card .art img { position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; }
.card .ph { position: absolute; top: 0; left: 0; width: 100%; height: 100%; padding: .8rem; display: flex; align-items: center; justify-content: center; text-align: center; font-size: .85rem; font-weight: 500; color: var(--fg); background: linear-gradient(150deg, rgba(255,255,255,.35), rgba(120,140,175,.4)); }
.card.focus .art { transform: scale(1.09); border-color: #fff; box-shadow: 0 0 0 .18rem rgba(255,255,255,.9), 0 .9rem 1.8rem rgba(25,35,60,.45); z-index: 2; }
.card.focus .art::before { content: ""; position: absolute; top: 0; left: 0; width: 100%; height: 45%; background: linear-gradient(rgba(255,255,255,.22), rgba(255,255,255,0)); z-index: 1; }
.card .pb { position: absolute; bottom: .6rem; right: .7rem; left: .7rem; height: .3rem; border-radius: .2rem; background: rgba(255,255,255,.4); overflow: hidden; direction: ltr; z-index: 1; }
.card .pb i { display: block; height: 100%; background: #fff; }
.card .tag { position: absolute; top: .45rem; right: .45rem; background: rgba(28,36,52,.55); color: #fff; font-size: .7rem; font-weight: 500; padding: 0 .45rem; border-radius: .35rem; direction: ltr; z-index: 1; text-shadow: none; }
.cap { padding-top: .55rem; font-size: .85rem; line-height: 1.35; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--mut); }
.cap small { display: block; font-size: .75rem; color: var(--dim); overflow: hidden; text-overflow: ellipsis; }
.card.poster .cap { opacity: 0; height: 2.2rem; }
.card.poster.focus .cap { opacity: 1; }
.card.focus .cap { color: var(--fg); padding-top: 1.1rem; }
.card.more .art { display: flex; align-items: center; justify-content: center; background: var(--glass); }
.card.more .art span { font-size: 1rem; font-weight: 500; color: var(--fg); }

/* ===== side list + poster grid (movies, series, library) ===== */
.sg { position: absolute; top: 5.4rem; left: 0; right: 0; bottom: 0; display: flex; padding: 0 var(--side) 0 2.4rem; }
.sg-side { width: 15.5rem; flex: none; height: 100%; padding: .4rem .3rem 3rem; }
.sg-src { margin: 0 .2rem .9rem; }
.sg-item { display: flex; align-items: center; padding: .6rem .9rem; border-radius: .9rem; color: var(--mut); font-size: .98rem; font-weight: 500; margin-bottom: .2rem; white-space: nowrap; overflow: hidden; transition: transform .15s; }
.sg-item .ic { width: 1.6rem; height: 1.3rem; flex: none; margin-left: .7rem; display: flex; align-items: center; justify-content: center; }
.sg-item .ic svg { width: 1.25rem; height: 1.25rem; }
.sg-item .nm { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.sg-item.sel { background: rgba(255,255,255,.88); color: var(--ink); text-shadow: none; }
.sg-item.focus { background: #fff; color: var(--ink); transform: scale(1.04); text-shadow: none; box-shadow: var(--shadow); }
.sg-main { flex: 1; min-width: 0; height: 100%; display: flex; flex-direction: column; margin-right: 1.4rem; }
.sg-head { flex: none; display: flex; align-items: baseline; padding: .2rem .6rem .4rem 0; }
.sg-title { font-size: 1.7rem; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sg-count { color: var(--dim); font-size: .9rem; margin-right: .9rem; flex: none; }
.sg-box { flex: 1; min-height: 0; }
.sg-grid { display: -webkit-flex; display: flex; -webkit-flex-wrap: wrap; flex-wrap: wrap; align-items: flex-start; padding: .9rem 1.1rem 5rem 0; margin-left: -1.2rem; }
.sg-grid .card { margin: 0 0 1.4rem 1.2rem; }
.sg-grid .card.poster { width: 10.6rem; }
.sg-grid .card.poster .art { height: 15.6rem; }
.sg-grid .card.poster .cap { opacity: 1; height: auto; color: var(--dim); }
.sg-grid .card.poster.focus .cap { color: var(--fg); }
.sg-grid .card.wide { width: 17.6rem; }
.sg-grid .card.wide .art { height: 9.9rem; }
.sg-empty { color: var(--mut); padding: 3rem 0; width: 100%; text-align: center; font-size: 1.05rem; }

/* see-all overlay (kept for the home rows) */
.gv-head { display: flex; justify-content: space-between; align-items: center; padding: 2rem var(--side) .6rem; }
.gv-tt { flex: 1; min-width: 0; }
#gv-title { font-size: 2rem; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; line-height: 1.3; }
#gv-count { color: var(--dim); font-size: .9rem; }
#gv-q { width: 22rem; flex: none; margin: 0 1.2rem; padding: .55rem 1rem; border-radius: 2rem; font-size: 1rem; }
.vscroll { position: absolute; top: 7rem; bottom: 0; left: 0; width: 100%; overflow-y: auto; overflow-x: hidden; }
.vscroll::-webkit-scrollbar, .vscroll2::-webkit-scrollbar { width: 0; }
.vscroll2 { overflow-y: auto; overflow-x: hidden; }
#gv-grid { display: -webkit-flex; display: flex; -webkit-flex-wrap: wrap; flex-wrap: wrap; align-items: flex-start; padding: 1rem var(--side) 4rem; }
#gv-grid .card { flex: none; width: 9.3rem; min-width: 0; margin: 0 0 1.6rem 1.15rem; }
#gv-grid .card:nth-child(7n) { margin-left: 0; }
#gv-grid .card .art { height: 13.95rem; }
#gv-grid .card .cap { opacity: 1; color: var(--dim); height: auto; }
#gv-grid .card.focus .cap { color: var(--fg); }
.empty { color: var(--mut); padding: 2rem 0; width: 100%; text-align: center; }

/* ===== search: field, quick chips, on-screen keyboard ===== */
.search-top { padding: 5.6rem var(--side) .3rem; }
.search-top input { font-size: 1.2rem; padding: .75rem 1.3rem; border-radius: 1.5rem; }
.search-msg { padding: .35rem var(--side) 0; color: var(--dim); font-size: .9rem; min-height: 1.7rem; }
.chips-h { padding: .3rem var(--side) .4rem; font-size: .95rem; font-weight: 500; color: var(--mut); }
.chips { padding: 0 var(--side); white-space: nowrap; overflow: hidden; height: 2.6rem; }
.chips .pill { margin-left: .6rem; }
.kb { padding: .9rem var(--side) .4rem; text-align: center; }
.kb-row { display: flex; justify-content: center; margin-bottom: .45rem; }
.kb-row.ltr { direction: ltr; }
.key { min-width: 2.75rem; height: 2.5rem; line-height: 2.5rem; padding: 0 .5rem; margin: 0 .22rem; border-radius: .65rem; background: var(--glass); border: .07rem solid rgba(255,255,255,.35); font-size: 1.05rem; font-weight: 500; transition: transform .12s; }
.key.wide { min-width: 6.5rem; font-size: .9rem; }
.key.focus { background: #fff; color: var(--ink); transform: scale(1.12); text-shadow: none; box-shadow: var(--shadow); }

/* ===== details ===== */
#d-bg { position: absolute; top: 0; left: 0; width: 100%; height: 100%; }
#d-bg img { position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; }
.d-shade { position: absolute; top: 0; left: 0; width: 100%; height: 100%;
  background: linear-gradient(to left, rgba(40,52,78,.72) 0%, rgba(40,52,78,.4) 40%, rgba(40,52,78,0) 72%),
              linear-gradient(to top, #8195b3 0%, rgba(129,149,179,.82) 22%, rgba(129,149,179,0) 55%); }
#d-pin { position: absolute; top: 0; left: 0; width: 100%; transition: transform .35s ease; }
.d-main { padding: 7rem var(--side) 0; width: 38rem; min-height: 25rem; }
#d-title { font-size: 2.8rem; font-weight: 700; line-height: 1.15; margin-bottom: .55rem; text-shadow: 0 .15rem .8rem rgba(20,30,50,.45); }
#d-meta { color: var(--mut); font-size: .95rem; margin-bottom: .7rem; }
#d-meta .rate { display: inline-block; border: .08rem solid var(--mut); border-radius: .3rem; padding: 0 .35rem; font-size: .78rem; margin-left: .3rem; direction: ltr; }
#d-plot { color: rgba(255,255,255,.95); line-height: 1.6; max-height: 4.8rem; overflow: hidden; margin-bottom: 1.3rem; }
#d-btns { margin-bottom: 1.4rem; }
#d-extra { padding-bottom: 3rem; }
.seasons { padding: 0 var(--side) .2rem; }
.seasons .pill { margin: 0 0 .4rem .6rem; }
.seasons .pill.on2 { background: rgba(255,255,255,.88); color: var(--ink); text-shadow: none; }
.d-info { padding: 1rem var(--side) 0; color: var(--mut); font-size: .9rem; line-height: 1.8; }
.d-info b { color: var(--fg); font-weight: 500; margin-left: .5rem; }

/* ===== settings ===== */
.set-wrap { padding: 2.6rem var(--side); }
.set-wrap h1 { font-size: 2rem; margin-bottom: 1.2rem; }
.set-box { background: var(--glass); border: .07rem solid var(--edge); box-shadow: var(--shadow); border-radius: 1.1rem; padding: 1rem 1.4rem; margin-bottom: 1rem; min-height: 3rem; line-height: 1.9; }
.set-row { margin-bottom: 1rem; }
.set-row .pill { margin: 0 0 .6rem .7rem; }

/* ===== player (stays dark) ===== */
#player { background: #000; text-shadow: none; }
#video { width: 100%; height: 100%; background: #000; }
#osd { position: absolute; top: 0; left: 0; width: 100%; height: 100%; display: none; background: linear-gradient(to top, rgba(0,0,0,.85) 0%, rgba(0,0,0,0) 38%); }
#osd.on { display: block; }
#osd-bot { position: absolute; bottom: 0; left: 0; width: 100%; padding: 0 var(--side) 2.2rem; }
#p-sub { color: rgba(255,255,255,.7); font-size: .9rem; }
#p-title { font-size: 1.5rem; font-weight: 700; margin-bottom: .9rem; }
#p-bar { position: relative; height: .32rem; background: rgba(255,255,255,.28); border-radius: .2rem; direction: ltr; }
#p-fill { position: absolute; left: 0; top: 0; height: 100%; width: 0; background: #fff; border-radius: .2rem; }
#p-knob { position: absolute; top: 50%; width: .9rem; height: .9rem; margin: -.45rem 0 0 -.45rem; border-radius: 50%; background: #fff; left: 0; display: none; }
#p-bar.seek #p-knob { display: block; }
#p-times { display: flex; justify-content: space-between; direction: ltr; margin-top: .55rem; font-size: .9rem; color: rgba(255,255,255,.7); font-weight: 500; }
#p-state { color: #fff; }
#p-err { position: absolute; top: 40%; left: 10%; width: 80%; text-align: center; font-size: 1.15rem; color: #ffb4ab; display: none; white-space: pre-line; }
