.lv-row .lg { width: 3rem; height: 2.1rem; margin-left: .9rem; flex: none; position: relative; }
.lv-row .lg img { width: 100%; height: 100%; object-fit: contain; }
.lv-row .rn { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
