var maps = {};
function buildMap(rows, type) {
  var t = type === 'movie' ? 0 : 1, byTY = {}, byT = {};
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i];
    if (r[0] !== t) continue;
    var n = normTitle(r[2]);
    if (!n) continue;
    var y = yearOf(r[2]);
    if (y) { if (!byTY[n + '|' + y]) byTY[n + '|' + y] = r; }
    if (!byT[n]) byT[n] = r;
