// ---- details for one title (Arabic plot when TMDB has it, else English) + YouTube trailer id ----
function ytId(s) {
  s = String(s || '').trim();
  if (/^[\w-]{11}$/.test(s)) return s;
  var m = /(?:v=|youtu\.be\/|embed\/|shorts\/)([\w-]{11})/.exec(s);
  return m ? m[1] : '';
}
T.ytId = ytId;
function cleanName(s) {
  return String(s || '').replace(/^[A-Za-z]{2,3}\s*[|:-]\s+/, '').replace(/\[[^\]]*\]|\([^)]*\)/g, ' ')
