      key('⌫', '', function () { input.value = input.value.slice(0, -1); changed(); }),
      key('مسح', 'wide', function () { input.value = ''; changed(); }),
      key(kbMode === 'en' ? 'عربي' : 'ABC', 'wide', function () { kbMode = kbMode === 'en' ? 'ar' : 'en'; kbBack = kbMode; drawKb(kbMode === 'en' ? 'عربي' : 'ABC'); }),
      key(kbMode === 'num' ? 'حروف' : '123', 'wide', function () { if (kbMode === 'num') kbMode = kbBack; else kbMode = 'num'; drawKb(kbMode === 'num' ? 'حروف' : '123'); })
    ];
    acts.forEach(function (k) { act.appendChild(k); if (focusLabel && k.textContent === focusLabel) refocus = k; });
    kb.appendChild(act);
