  chipsH.style.display = chips.style.display = 'none';
  p.pin.appendChild(chipsH); p.pin.appendChild(chips);
  var chipsDone = false;
  function loadChips() {
    if (chipsDone || !(window.TMDB && window.TMDB.ready())) return;
    chipsDone = true;
    build().then(function () {
      return Promise.all([window.TMDB.load(window.TMDB.rows('movie')[0], 'movie', index),
        window.TMDB.load(window.TMDB.rows('series')[0], 'series', index)]);
    }).then(function (r) {
      var out = [];
      for (var i = 0; out.length < 5 && (i < r[0].length || i < r[1].length); i++) {
        if (r[0][i]) out.push(r[0][i]);
        if (r[1][i] && out.length < 5) out.push(r[1][i]);
      }
      if (!out.length) return;
      clear(chips);
      out.forEach(function (row) {
