  }
  var msg = h('div', 'search-msg', 'اكتب اسم فيلم أو مسلسل بالعربي أو الإنجليزي'); p.pin.appendChild(msg);
  var sm = p.addShelf('أفلام'), ss = p.addShelf('مسلسلات');
  sm.hide(); ss.hide();
  var index = null, building = null, refreshing = false, qT = null, lastQ = '';
  var MAXAGE = 12 * 3600 * 1000;
  // compact rows: [type 0=movie 1=series, id, name, icon, ext, rating, added] — names normalised once into idxN
  var idxN = null;
  function setIndex(rows) { index = rows; idxN = rows.map(function (r) { return norm(r[2]); }); }
  function fromRow(r) {
    return r[0] === 0 ? { t: 'movie', id: r[1], name: r[2], icon: r[3], ext: r[4] || 'mp4', rating: r[5] || 0, added: r[6] || 0 }
      : { t: 'series', id: r[1], name: r[2], icon: r[3], rating: r[5] || 0, added: r[6] || 0 };
  }
  function idxKey() { return 'idx:' + cfg.server + '|' + cfg.user; }
  function fetchFresh() {
    var rows = [];
    function grab(action, type) {
      return api(action, null, true).then(function (d) {
        arr(d).forEach(function (r) {
          if (type === 0) rows.push([0, r.stream_id, r.name || '', r.stream_icon || '', r.container_extension || 'mp4', parseFloat(r.rating) || 0, parseInt(r.added, 10) || 0]);
          else rows.push([1, r.series_id, r.name || '', r.cover || '', '', parseFloat(r.rating) || 0, parseInt(r.last_modified, 10) || 0]);
        });
      });
    }
    return grab('get_vod_streams', 0).then(function () { return grab('get_series', 1); }).then(function () {
      idb.set(idxKey(), { ts: Date.now(), rows: rows });
      return rows;
    });
  }
  p.opts.firstFocus = function () { return input; };
  input._onfocus = function () { p.top(); };
