    if (dir === 'up') return tabEls.search;
    return 'stop';
  };
  // 1) saved index from IndexedDB → instant  2) none saved → download once  3) older than 12h → refresh quietly in the background
  function build() {
    if (index) return Promise.resolve();
    if (building) return building;
    building = idb.get(idxKey()).then(function (saved) {
      if (saved && saved.rows && saved.rows.length) {
        setIndex(saved.rows);
        if (Date.now() - saved.ts > MAXAGE && !refreshing && !vis('player')) {
          refreshing = true;
          fetchFresh().then(function (rows) { setIndex(rows); refreshing = false; }).catch(function () { refreshing = false; });
        }
        return;
      }
      msg.textContent = 'بجهّز البحث لأول مرة بس… بعد كده هيبقى فوري';
      return fetchFresh().then(function (rows) { setIndex(rows); if (!lastQ) msg.textContent = 'اكتب اسم فيلم أو مسلسل بالعربي أو الإنجليزي'; });
    }).then(function () { building = null; }, function (e) { building = null; msg.textContent = e.message; throw e; });
    return building;
  }
  function run() {
    var q = norm(input.value.trim());
    if (q === lastQ) return;
    lastQ = q;
    if (q.length < 2) { sm.hide(); ss.hide(); msg.textContent = 'اكتب حرفين على الأقل'; return; }
    build().then(function () {
      if (q !== lastQ) return;
      var words = q.split(/\s+/), mv = [], sr = [];
      for (var i = 0; i < index.length && (mv.length < 40 || sr.length < 40); i++) {
        var n = idxN[i], ok = true;
        for (var j = 0; j < words.length; j++) if (n.indexOf(words[j]) < 0) { ok = false; break; }
        if (!ok) continue;
