      mv.sort(rank); sr.sort(rank);
      msg.textContent = (mv.length || sr.length) ? '' : 'مفيش نتائج لـ "' + input.value.trim() + '"';
      sm.setTitle('أفلام'); ss.setTitle('مسلسلات');
      sm.setCards(mv.map(function (it) { return itemCard(it); }));
      ss.setCards(sr.map(function (it) { return itemCard(it); }));
      sm.loaded = ss.loaded = true;
    });
  }
  input._submit = run;
  // text typed on the phone ("اكتب على التليفزيون")
  p.remote = function (txt, act) {
    input.value = txt;
    msg.textContent = txt ? '📱 من الموبايل: ' + txt : 'اكتب من الموبايل أو من الريموت';
    clearTimeout(qT);
    if (act === 'go') {
      run();
      var tries = 0, t = setInterval(function () {
        var e = sm.entry() || ss.entry();
        if (e || ++tries > 20) { clearInterval(t); if (e) { dropFocus(); setFocus(e); } }
      }, 250);
    } else qT = setTimeout(run, 200);
  };
  input.addEventListener('input', function () { clearTimeout(qT); qT = setTimeout(run, 500); });
  p.enter = function () { build().then(loadChips).catch(function () {}); };  // warm up as soon as the tab opens
  p.ensure = function () { return build().then(function () { return index; }); };
  p.fromRow = fromRow;
  return p;
}

// ================= see-all grid =================
var SORTS = ['الترتيب: الأحدث', 'الترتيب: التقييم', 'الترتيب: الاسم', 'الترتيب: الافتراضي'];
var gv = { items: [], norms: null, sort: 0, q: '', qT: null };
function openGrid(title, items) {
  gv.items = items; gv.sort = 0; gv.q = ''; gv.norms = null;
  $('gv-title').textContent = title;
  $('gv-sort').textContent = SORTS[0];
  $('gv-q').value = '';
  openLayer('gridv');
  renderGrid();
}
function renderGrid(keepFocus) {
  var items = gv.items.slice();
  if (gv.q) {
    if (!gv.norms) gv.norms = gv.items.map(function (it) { return norm(it.name); });
    var words = gv.q.split(/\s+/), nm = gv.norms, src = gv.items;
    items = [];
    for (var i = 0; i < src.length; i++) {
      var ok = true;
      for (var j = 0; j < words.length; j++) if (nm[i].indexOf(words[j]) < 0) { ok = false; break; }
      if (ok) items.push(src[i]);
    }
  }
  if (gv.sort === 0) items.sort(function (a, b) { return b.added - a.added; });
  else if (gv.sort === 1) items.sort(function (a, b) { return b.rating - a.rating; });
  else if (gv.sort === 2) items.sort(function (a, b) { return a.name < b.name ? -1 : a.name > b.name ? 1 : 0; });
  var box = $('gv-grid'); clear(box); $('gv-box').scrollTop = 0;
  var n = 0, CH = 42;
  function more() {
    var end = Math.min(items.length, n + CH), frag = document.createDocumentFragment();
    for (; n < end; n++) {
      (function (i) {
        var c = itemCard(items[i]);
        c._onfocus = function () { vReveal(c); if (i >= n - 14) more(); };
        frag.appendChild(c);
      })(n);
    }
    box.appendChild(frag);
