    var inp = document.activeElement;
    if (k === 13) { ev.preventDefault(); inp.blur(); if (inp._submit) inp._submit(); else move('down'); }
    else if (k === 461 || k === 27) { ev.preventDefault(); inp.blur(); }
    else if (k === 38) { ev.preventDefault(); inp.blur(); move('up'); }
    else if (k === 40) { ev.preventDefault(); inp.blur(); move('down'); }
    return;
  }
  if ([13, 37, 38, 39, 40, 461, 27, 8, 33, 34, 403, 404, 405, 406, 415, 19, 413, 417, 412].indexOf(k) < 0) return;
  ev.preventDefault();
  if (vis('player') && !vis('dialog')) { playerKey(k); return; }
  switch (k) {
    case 37: move('left'); break;
    case 39: move('right'); break;
    case 38: move('up'); break;
    case 40: move('down'); break;
    case 13:
      if (!cur) { move('down'); break; }
      if (cur.tagName === 'INPUT') { cur.focus(); break; }
      if (cur._long) {
        var target = cur;
        ok.down = true;
        ok.safety = setTimeout(function () { ok.down = false; }, 4000);
        ok.t = setTimeout(function () { ok.t = null; if (cur === target) target._long(); }, 650);
        break;
      }
      if (cur._ok) cur._ok();
      break;
    case 405: if (cur && cur._fav) cur._fav(); break;
    case 461: case 27: case 8: onBack(); break;
  }
});
document.addEventListener('click', function (ev) {
  if (vis('player') && !vis('dialog')) { if (pl.o && pl.o.kind !== 'live') togglePause(); else showOSD(); return; }
  var el = ev.target.closest ? ev.target.closest('.f') : null;
  if (!el || !topLayer().contains(el)) return;
  setFocus(el);
  if (el.tagName === 'INPUT') { el.focus(); return; }
  if (el._ok) el._ok();
});
